local WireDrawerMaker = {}
local PRODUCTS = {
    simple_iron_wire = { name = "Preprosta železna žica", ironCost = 2, time = 3, cost = 60, science = 15, happiness = 1, description = "Preprosta železna žica za uporabo." },
    brass_wire = { name = "Medeninasta žica", brassCost = 2, ironCost = 1, time = 5, cost = 160, science = 28, happiness = 1, prestige = 2, description = "Medeninasta žica za trgovce." },
    silver_wire = { name = "Srebrna žica", silverCost = 2, brassCost = 1, ironCost = 1, time = 8, cost = 400, science = 42, happiness = 2, prestige = 6, description = "Srebrna žica za plemiče." },
    gold_wire = { name = "Zlata žica", goldCost = 2, silverCost = 1, brassCost = 1, ironCost = 1, time = 12, cost = 950, science = 56, happiness = 3, prestige = 14, description = "Zlata žica za visoke plemiče." },
    jewel_wire = { name = "Draguljasta žica", goldCost = 2, silverCost = 1, brassCost = 1, ironCost = 1, jewelCost = 1, time = 16, cost = 2100, science = 72, happiness = 5, prestige = 27, description = "Žica z draguljem za visoko plemstvo." },
    royal_grand_wire = { name = "Kraljevski veliki žica", goldCost = 3, silverCost = 2, brassCost = 1, ironCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 4800, science = 90, happiness = 12, prestige = 58, description = "Velika kraljevska žica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    wire_workshop = { name = "Žična delavnica", cost = { gold = 260, wood = 120, stone = 140, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    drawing_loft = { name = "Vlečna podstrešje", cost = { gold = 950, wood = 280, stone = 280, silver = 6, brass = 6 }, upkeep = 22, qualityBonus = 18 },
    master_wire_atelier = { name = "Mojstrski žični atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_wire_palace = { name = "Kraljevska žična palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
WireDrawerMaker.ironStock = 14; WireDrawerMaker.brassStock = 14; WireDrawerMaker.silverStock = 8; WireDrawerMaker.goldStock = 6; WireDrawerMaker.jewelStock = 4; WireDrawerMaker.pearlStock = 4
WireDrawerMaker.productStock = {}; WireDrawerMaker.buildings = {}; WireDrawerMaker.maker = nil; WireDrawerMaker.activeMaking = {}; WireDrawerMaker.totalProducts = 0; WireDrawerMaker.dayTimer = 0
function WireDrawerMaker.init() WireDrawerMaker.ironStock=14; WireDrawerMaker.brassStock=14; WireDrawerMaker.silverStock=8; WireDrawerMaker.goldStock=6; WireDrawerMaker.jewelStock=4; WireDrawerMaker.pearlStock=4; WireDrawerMaker.productStock={}; WireDrawerMaker.buildings={}; WireDrawerMaker.maker=nil; WireDrawerMaker.activeMaking={}; WireDrawerMaker.totalProducts=0; WireDrawerMaker.dayTimer=0; print("[WireDrawerMaker] Royal Wire Drawer Maker System initialized (6 products, 4 buildings)") end
function WireDrawerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WireDrawerMaker.maker={name=n or ("Žičar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žičar najet: %s (spretnost: %d)",WireDrawerMaker.maker.name,s),"success") end; return true end
function WireDrawerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WireDrawerMaker.build(id) local ok,e=WireDrawerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WireDrawerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WireDrawerMaker.getQualityBonus() local b=0; for _,bd in ipairs(WireDrawerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WireDrawerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and WireDrawerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and WireDrawerMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and WireDrawerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WireDrawerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WireDrawerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WireDrawerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WireDrawerMaker.buildings==0 then return false,"Potrebna žična delavnica" end; if not WireDrawerMaker.maker then return false,"Potreben žičar" end; return true end
function WireDrawerMaker.make(pt,qty) qty=qty or 1; local ok,e=WireDrawerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then WireDrawerMaker.ironStock=WireDrawerMaker.ironStock-d.ironCost*qty end; if d.brassCost then WireDrawerMaker.brassStock=WireDrawerMaker.brassStock-d.brassCost*qty end; if d.silverCost then WireDrawerMaker.silverStock=WireDrawerMaker.silverStock-d.silverCost*qty end; if d.goldCost then WireDrawerMaker.goldStock=WireDrawerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WireDrawerMaker.jewelStock=WireDrawerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WireDrawerMaker.pearlStock=WireDrawerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WireDrawerMaker.maker then t=math.max(1,t-math.floor(WireDrawerMaker.maker.skill/13)) end; table.insert(WireDrawerMaker.activeMaking,{id="wiredrawer_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vleka: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WireDrawerMaker.completeMaking(m) local q=1.0+(WireDrawerMaker.getQualityBonus()/100); if WireDrawerMaker.maker then q=q+(WireDrawerMaker.maker.skill/140) end; q=math.min(2.5,q); WireDrawerMaker.productStock[m.productType]=(WireDrawerMaker.productStock[m.productType] or 0)+m.quantity; WireDrawerMaker.totalProducts=WireDrawerMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WireDrawerMaker.maker then WireDrawerMaker.maker.itemsMade=WireDrawerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WireDrawerMaker.maker.skill=math.min(100,WireDrawerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"wiredrawer.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function WireDrawerMaker.update(dt) if not _G.state then return end; WireDrawerMaker.dayTimer=WireDrawerMaker.dayTimer+dt; if WireDrawerMaker.dayTimer>=30 then WireDrawerMaker.dayTimer=0; for i=#WireDrawerMaker.activeMaking,1,-1 do local m=WireDrawerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WireDrawerMaker.completeMaking(m); table.remove(WireDrawerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WireDrawerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WireDrawerMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WireDrawerMaker.getStats() return {ironStock=WireDrawerMaker.ironStock,brassStock=WireDrawerMaker.brassStock,silverStock=WireDrawerMaker.silverStock,goldStock=WireDrawerMaker.goldStock,jewelStock=WireDrawerMaker.jewelStock,pearlStock=WireDrawerMaker.pearlStock,productStock=WireDrawerMaker.productStock,numBuildings=#WireDrawerMaker.buildings,hasMaker=WireDrawerMaker.maker~=nil,makerName=WireDrawerMaker.maker and WireDrawerMaker.maker.name or "—",makerSkill=WireDrawerMaker.maker and WireDrawerMaker.maker.skill or 0,activeMaking=#WireDrawerMaker.activeMaking,totalProducts=WireDrawerMaker.totalProducts} end
return WireDrawerMaker
